// Some portions generated by Claude Code
package org.eclipse.rdf4j.sail.lmdb.evaluation;

import java.util.ArrayList;
import java.util.List;
import java.util.concurrent.atomic.AtomicLong;

import org.eclipse.rdf4j.common.annotation.Experimental;

/**
 * Bounded local reorder for factorization payoff. Within one {@link MultiJoinPlan} join group it considers orders
 * reachable by at most {@link #MAX_MOVES} moves — each move shifts one statement pattern one position up or down (one
 * adjacent transposition; the swap partner slides one position the other way) — and adopts the order that lets the
 * factorized machinery claim strictly more trailing patterns than the incumbent selection. Ties always keep the
 * incumbent, mirroring the join-order tie-break doctrine: the compiler order wins unless deviating buys something
 * structural.
 *
 * <p>
 * Guards: only adjacent {@link PatternPlan} pairs may swap — every other child is an immovable wall; a depth-0 swap is
 * allowed only when no external morsel root is required and the incoming pattern's static estimate is within a factor-2
 * band of the displaced root's — and the adopted order's final root must itself be within that band of the
 * <em>incumbent</em> root, so chained swaps cannot drift outside it; an adopted order may not introduce a cartesian
 * step, where connectivity counts the seed mask (slots bound outside the join group at open time); and a pattern may
 * not leave the flat prefix when it is more selective than every child remaining there — the same pruning-floor rule
 * the sink applies. The search is purely structural and deterministic, so structurally equal plan instances (parallel
 * worker forks of the same join) always select the same order.
 */
@Experimental
final class LmdbNativeFactorizedReorder {

	/** Maximum number of single-position moves per join group. */
	static final int MAX_MOVES = 3;
	/** Swap positions considered around the incumbent flat/tail boundary: {@code [boundary - 3, boundary + 2]}. */
	private static final int WINDOW_BEFORE = 3;
	private static final int WINDOW_AFTER = 2;

	/** Test observability: adopted reorders on the rows selection path. */
	static final AtomicLong ROWS_REORDERS = new AtomicLong();
	/** Test observability: adopted reorders on the aggregate tail selection path. */
	static final AtomicLong TAIL_REORDERS = new AtomicLong();

	static boolean enabled() {
		return !"false".equals(System.getProperty("rdf4j.lmdb.factorizedReorder.enabled"));
	}

	private LmdbNativeFactorizedReorder() {
	}

	/** Claimed-tail payoff of one candidate order; larger is better, 0 means the factorization declines. */
	private interface Payoff {
		int of(SlotPlan[] candidateOrder);
	}

	/**
	 * Attempts to strictly shorten the planned flat prefix of the rows-side selection with at most three
	 * single-position pattern moves. Returns the improved derived plan, or null to keep the incumbent. Inert for
	 * ordered execution ({@code requiredPrefixMask != 0}): the ordered path proves its sorted prefix from the concrete
	 * scan and probe structure, which a permuted prefix would silently break.
	 */
	static MultiJoinPlan.OrderedPlan improveRows(MultiJoinPlan plan, MultiJoinPlan.OrderedPlan incumbent,
			long seedMask, long requiredPrefixMask, int minimumFlatCount) {
		if (!enabled() || requiredPrefixMask != 0L || incumbent.order.length < 3) {
			return null;
		}
		int n = incumbent.order.length;
		int incumbentPayoff = n - LmdbNativeFactorizedRows.plannedFlatCountFor(plan, incumbent, seedMask,
				requiredPrefixMask, minimumFlatCount);
		Payoff payoff = candidateOrder -> {
			MultiJoinPlan.OrderedPlan candidate = plan.deriveExplicit(seedMask, candidateOrder);
			return n - LmdbNativeFactorizedRows.plannedFlatCountFor(plan, candidate, seedMask, requiredPrefixMask,
					minimumFlatCount);
		};
		SlotPlan[] best = search(incumbent.order, seedMask, incumbentPayoff, minimumFlatCount, payoff);
		if (best == null) {
			return null;
		}
		ROWS_REORDERS.incrementAndGet();
		return plan.deriveExplicit(seedMask, best);
	}

	/**
	 * Attempts to strictly grow the claimed branch set of the aggregate tail selection with at most three
	 * single-position pattern moves. Returns the improved selection (whose probe the caller adopts), or null to keep
	 * the incumbent; every probe built for a non-adopted candidate is discarded here.
	 */
	static FactorizedTail.Selection improveTail(MultiJoinPlan plan, FactorizedTail.Selection incumbent, long seedMask,
			int[] groupSlots, AggregateSpec[] aggregates, LmdbNativeAttemptMetrics metrics) {
		if (!enabled() || incumbent.derived.order.length < 3) {
			return null;
		}
		int incumbentPayoff = incumbent.tail == null ? 0 : incumbent.tail.branchCount();
		Payoff payoff = candidateOrder -> {
			MultiJoinPlan.OrderedPlan candidate = plan.deriveExplicit(seedMask, candidateOrder);
			FactorizedTail probe = FactorizedTail.probe(candidate, plan.filters, seedMask, groupSlots, aggregates,
					metrics);
			if (probe == null) {
				return 0;
			}
			int claimed = probe.branchCount();
			probe.discardUnopenedProbe();
			return claimed;
		};
		SlotPlan[] best = search(incumbent.derived.order, seedMask, incumbentPayoff, 0, payoff);
		if (best == null) {
			return null;
		}
		MultiJoinPlan.OrderedPlan derived = plan.deriveExplicit(seedMask, best);
		FactorizedTail tail = FactorizedTail.probe(derived, plan.filters, seedMask, groupSlots, aggregates, metrics);
		if (tail == null || tail.branchCount() <= incumbentPayoff) {
			// the probe is deterministic, so this cannot happen; refuse rather than adopt an unproven order
			if (tail != null) {
				tail.discardUnopenedProbe();
			}
			return null;
		}
		TAIL_REORDERS.incrementAndGet();
		return new FactorizedTail.Selection(derived, tail);
	}

	/**
	 * Enumerates every order within {@link #MAX_MOVES} adjacent transpositions inside the boundary window
	 * (breadth-first, deduplicated), scores each exactly once, and returns the best strictly-improving order that
	 * passes the connectivity and pruning-floor guards, or null. Ties go to fewer moves, then discovery order, which
	 * keeps the result deterministic across structurally equal plan instances.
	 */
	private static SlotPlan[] search(SlotPlan[] incumbent, long seedMask, int incumbentPayoff, int minimumFlatCount,
			Payoff payoff) {
		int n = incumbent.length;
		int boundary = n - incumbentPayoff - 1;
		if (boundary < 0) {
			return null;
		}
		int lo = Math.max(0, boundary - WINDOW_BEFORE);
		int hi = Math.min(n - 2, boundary + WINDOW_AFTER);
		if (lo > hi) {
			return null;
		}
		List<SlotPlan[]> states = new ArrayList<>();
		List<Integer> moves = new ArrayList<>();
		List<SlotPlan[]> level = List.<SlotPlan[]>of(incumbent);
		for (int depth = 1; depth <= MAX_MOVES && !level.isEmpty(); depth++) {
			List<SlotPlan[]> next = new ArrayList<>();
			for (SlotPlan[] state : level) {
				for (int k = lo; k <= hi; k++) {
					if (!(state[k] instanceof PatternPlan) || !(state[k + 1] instanceof PatternPlan)) {
						continue;
					}
					if (k == 0 && (minimumFlatCount > 0
							|| !withinRootBand((PatternPlan) state[1], (PatternPlan) state[0]))) {
						continue;
					}
					SlotPlan[] candidate = state.clone();
					candidate[k] = state[k + 1];
					candidate[k + 1] = state[k];
					if (sameOrder(candidate, incumbent) || seen(states, candidate)) {
						continue;
					}
					states.add(candidate);
					moves.add(depth);
					next.add(candidate);
				}
			}
			level = next;
		}
		boolean[] incumbentDisconnected = disconnected(incumbent, seedMask);
		int incumbentFlat = n - incumbentPayoff;
		SlotPlan[] best = null;
		int bestPayoff = incumbentPayoff;
		int bestMoves = 0;
		for (int i = 0; i < states.size(); i++) {
			SlotPlan[] candidate = states.get(i);
			int claimed = payoff.of(candidate);
			if (claimed <= incumbentPayoff) {
				continue;
			}
			if (best != null && (claimed < bestPayoff || (claimed == bestPayoff && moves.get(i) >= bestMoves))) {
				continue;
			}
			// a changed root implies both roots are PatternPlans: only k==0 swaps between patterns move position 0
			if (candidate[0] != incumbent[0]
					&& !withinRootBand((PatternPlan) candidate[0], (PatternPlan) incumbent[0])) {
				continue;
			}
			if (!connectivityPreserved(incumbent, incumbentDisconnected, candidate, seedMask)
					|| !passesPruningFloor(incumbent, incumbentFlat, candidate, n - claimed)) {
				continue;
			}
			best = candidate;
			bestPayoff = claimed;
			bestMoves = moves.get(i);
		}
		return best;
	}

	/**
	 * The 2x band for depth-0 swaps: the incoming root's static estimate must be within a factor two of the displaced
	 * root's, both usable and positive. The root drives the whole scan, so its cardinality class must not change.
	 */
	private static boolean withinRootBand(PatternPlan incoming, PatternPlan displaced) {
		double in = incoming.staticEstimate;
		double out = displaced.staticEstimate;
		return Double.isFinite(in) && Double.isFinite(out) && in > 0D && out > 0D
				&& in <= 2D * out && out <= 2D * in;
	}

	private static boolean sameOrder(SlotPlan[] left, SlotPlan[] right) {
		for (int i = 0; i < left.length; i++) {
			if (left[i] != right[i]) {
				return false;
			}
		}
		return true;
	}

	private static boolean seen(List<SlotPlan[]> states, SlotPlan[] candidate) {
		for (SlotPlan[] state : states) {
			if (sameOrder(state, candidate)) {
				return true;
			}
		}
		return false;
	}

	/**
	 * Per depth: true when the child produces slots yet shares none with what is bound before it — the seed mask plus
	 * everything earlier children produce. Depth 0 is the driver and never disconnected; a child producing no slots is
	 * a pure existence check and never disconnected either.
	 */
	private static boolean[] disconnected(SlotPlan[] order, long seedMask) {
		boolean[] result = new boolean[order.length];
		long bound = seedMask;
		for (int d = 0; d < order.length; d++) {
			long produced = order[d].producedMask();
			result[d] = d > 0 && produced != 0L && (produced & bound) == 0L;
			bound |= produced;
		}
		return result;
	}

	/** No child may be disconnected in the candidate unless the same child already was in the incumbent order. */
	private static boolean connectivityPreserved(SlotPlan[] incumbent, boolean[] incumbentDisconnected,
			SlotPlan[] candidate, long seedMask) {
		boolean[] candidateDisconnected = disconnected(candidate, seedMask);
		for (int d = 0; d < candidate.length; d++) {
			if (!candidateDisconnected[d]) {
				continue;
			}
			boolean was = false;
			for (int i = 0; i < incumbent.length; i++) {
				if (incumbent[i] == candidate[d]) {
					was = incumbentDisconnected[i];
					break;
				}
			}
			if (!was) {
				return false;
			}
		}
		return true;
	}

	/**
	 * The sink's pruning-floor rule applied to reordering: selective patterns are the nested-loop prefix's pruning
	 * workhorses, so no pattern leaving the flat prefix may be more selective than every child remaining there; with no
	 * usable estimate left in the prefix the move is refused.
	 */
	private static boolean passesPruningFloor(SlotPlan[] incumbent, int incumbentFlat, SlotPlan[] candidate,
			int candidateFlat) {
		double floor = Double.POSITIVE_INFINITY;
		for (int d = 0; d < candidateFlat; d++) {
			double estimate = MultiJoinPlan.staticEstimateOf(candidate[d]);
			if (!Double.isNaN(estimate)) {
				floor = Math.min(floor, estimate);
			}
		}
		for (int i = 0; i < incumbentFlat; i++) {
			SlotPlan child = incumbent[i];
			int at = indexOf(candidate, child);
			if (at < candidateFlat) {
				continue;
			}
			if (!Double.isFinite(floor)) {
				return false;
			}
			double estimate = MultiJoinPlan.staticEstimateOf(child);
			if (Double.isNaN(estimate) || estimate < floor) {
				return false;
			}
		}
		return true;
	}

	private static int indexOf(SlotPlan[] order, SlotPlan child) {
		for (int i = 0; i < order.length; i++) {
			if (order[i] == child) {
				return i;
			}
		}
		return order.length;
	}
}
